CREATE TABLE IF NOT EXISTS oauth_tokens (
  account_label text PRIMARY KEY,
  access_token  text NOT NULL,
  refresh_token text,
  expires_at    timestamptz,
  updated_at    timestamptz DEFAULT now()
);
ALTER TABLE oauth_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_tokens_service_role ON oauth_tokens
  USING (auth.role() = 'service_role');

CREATE TABLE IF NOT EXISTS mcp_write_audit (
  id bigserial PRIMARY KEY,
  tool_name text NOT NULL,
  client_slug text,
  seller_id text,
  item_id text,
  payload jsonb NOT NULL,
  result text NOT NULL,
  created_at timestamptz DEFAULT now()
);
CREATE INDEX mcp_write_audit_tool_idx ON mcp_write_audit(tool_name, created_at DESC);
CREATE INDEX mcp_write_audit_client_idx ON mcp_write_audit(client_slug, created_at DESC);

CREATE TABLE IF NOT EXISTS agent_notes (
  id bigserial PRIMARY KEY,
  agent_name text NOT NULL,
  scope text NOT NULL,
  category text NOT NULL,
  note text NOT NULL,
  metadata jsonb,
  created_at timestamptz DEFAULT now()
);
CREATE INDEX agent_notes_scope_idx ON agent_notes(agent_name, scope, created_at DESC);
